import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'svg', 'eps', 'pdf', 'png', 'jpg'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_output_path(input_filename):
    base = os.path.splitext(input_filename)[0]
    timestamp = str(int(time.time() * 1000))
    hash_val = hashlib.md5((base + timestamp).encode()).hexdigest()[:8]
    return os.path.join(UPLOAD_DIR, f"{hash_val}_output.png")

@app.route('/api/convert', methods=['POST'])
def convert_image():
    """Convert uploaded image to PNG using ImageMagick."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'Empty filename'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    filename = secure_filename(file.filename)
    os.makedirs(UPLOAD_DIR, exist_ok=True)

    input_path = os.path.join(UPLOAD_DIR, filename)
    file.save(input_path)

    output_path = generate_output_path(filename)

    # Get optional resize parameter
    resize = request.form.get('resize', '800x600')
    density = request.form.get('density', '150')

    # Build ImageMagick convert command
    cmd = f'convert -density {density} -resize {resize} "{input_path}" "{output_path}"'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            stderr = result.stderr.decode('utf-8', errors='replace')
            # Log error but don't expose full stderr to client
            app.logger.error(f"Conversion failed: {stderr[:200]}")
            return jsonify({'error': 'Conversion failed'}), 500

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        return send_file(output_path, mimetype='image/png', as_attachment=True,
                        download_name='converted.png')
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Conversion timed out'}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)
        # Cleanup output after small delay handled by caller

@app.route('/api/metadata', methods=['POST'])
def get_metadata():
    """Extract image metadata using identify command."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    if not allowed_file(file.filename):
        return jsonify({'error': 'File type not allowed'}), 400

    filename = secure_filename(file.filename)
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    input_path = os.path.join(UPLOAD_DIR, filename)
    file.save(input_path)

    try:
        result = subprocess.run(
            ['identify', '-verbose', input_path],
            capture_output=True,
            timeout=10
        )
        metadata = result.stdout.decode('utf-8', errors='replace')
        return jsonify({'metadata': metadata})
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Timeout'}), 504
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
